/* cppi::71ba2a1e2608823776a382e136b7b14377d5ed44b8fe61f284722bca34b87a06 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-13' and end_date = '2025-05-13')
and start_date = '2025-05-13' and end_date = '2025-05-13'

/* cppi::d6b765cd6d874f140cc7758e665363e2c800e60571d6d26b038c0cfeaead536b */
